        Access: "read_only" | "standard" | "admin";
        /** @description HTTP-POST binding form fields. */
        AcsForm: {
            RelayState?: string | null;
            SAMLResponse: string;
        };
        ActionHeader: {
            name: string;
            /** @description Template. */
            value: string;
        };
        /** @description One outbound request; its response must be 2xx for the run to go on. */
        ActionHttpRequest: {
            /** @description JSON template sent as `application/json`; empty for no body. */
            body?: string;
            headers?: components["schemas"]["ActionHeader"][];
            /** @description GET, POST, PUT, PATCH or DELETE. */
            method: string;
            /** @description Template; scheme and host are literal. */
            url: string;
        };
        /** @description A field of the action's form. */
        ActionInput: {
            /** @description Pre-filled value (`true` / `false` for booleans). */
            default?: string;
            description?: string;
            /** @description Name used in templates (`{{inputs.<key>}}`): `[a-z0-9_]`. */
            key: string;
            kind: components["schemas"]["ActionInputKind"];
            label: string;
            /** @description Select only. */
            options?: string[];
            required?: boolean;
        };
        /** @enum {string} */
        ActionInputKind: "text" | "select" | "number" | "boolean";
        ActionStep: {
            /** @description Internal steps: a template per field. */
            fields?: {
                [key: string]: string;
            };
            kind: components["schemas"]["ActionStepKind"];
            /** @description Http only. */
            requests?: components["schemas"]["ActionHttpRequest"][];
        };
        /** @enum {string} */
        ActionStepKind: "http" | "create_incident" | "page_on_call" | "incident_comment" | "synthetic_run" | "run_workflow";
        AddResponder: {
            role: string;
            userId: string;
        };
        AdvisoryDetail: {
            aliases: string[];
            cwes: string[];
            details: string;
            id: string;
            /** Format: int64 */
            modified?: number | null;
            packages: components["schemas"]["AdvisoryPackageInfo"][];
            /** Format: int64 */
            published?: number | null;
            refs: components["schemas"]["AdvisoryRef"][];
            repositoriesAnalyzed: number;
            /** Format: double */
            score?: number | null;
            servicesAnalyzed: number;
            severity: string;
            source: string;
            summary: string;
            vector: string;
            /** @description The org's vulnerabilities from this advisory. */
            vulnerabilities: components["schemas"]["LibraryVulnerability"][];
        };
        AdvisoryFilter: {
            /** @default  */
            ecosystem: string;
            /**
             * @description impacted | not_impacted
             * @default
             */
            impact: string;
            /** @default 0 */
            limit: number;
            /** @default 0 */
            offset: number;
            /** @default  */
            query: string;
            /** @default [] */
            severity: string[];
        };
        AdvisoryPackageInfo: {
            ecosystem: string;
            fixed: string;
            package: string;
            ranges: components["schemas"]["AffectedRange"][];
        };
        AdvisoryPage: {
            advisories: components["schemas"]["AdvisorySummary"][];
            total: number;
        };
        AdvisoryRef: {
            type: string;
            url: string;
        };
        AdvisorySummary: {
            aliases: string[];
            cve?: string | null;
            ecosystems: string[];
            id: string;
            /** @description Some library of the org is in an affected range. */
            impacted: boolean;
            packages: string[];
            /** Format: int64 */
            published?: number | null;
            /** Format: double */
            score?: number | null;
            severity: string;
            summary: string;
        };
        /** @description One affected interval of a package: `[introduced, fixed)` or `[introduced, last_affected]`. */
        AffectedRange: {
            fixed?: string;
            introduced: string;
            last_affected?: string;
        };
        AnalyticsItem: {
            name: string;
            /** Format: double */
            value: number;
        };
        /** @enum {string} */
        AnalyticsPage: "home" | "users" | "devices" | "traffic" | "engagement" | "performance";
